#!/usr/bin/env python3
"""Exercise schema upgrade and restart recovery with synthetic data, never live state."""

import argparse
from contextlib import closing
import json
from pathlib import Path
import re
import sqlite3
import subprocess
import sys
import tarfile
import tempfile


# Frozen pre-versioning schema: this must not be generated by today's Store.
LEGACY_SCHEMA = """
CREATE TABLE binding (
    id TEXT PRIMARY KEY, owner TEXT NOT NULL, token TEXT NOT NULL,
    base_url TEXT NOT NULL, cursor TEXT NOT NULL DEFAULT '',
    enabled INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'ready',
    last_error TEXT);
CREATE TABLE messages (
    id TEXT PRIMARY KEY, account TEXT NOT NULL, peer TEXT NOT NULL,
    source_id TEXT NOT NULL, text TEXT NOT NULL, created_at REAL NOT NULL,
    context_token TEXT, state TEXT NOT NULL DEFAULT 'pending',
    UNIQUE(account,peer,source_id));
CREATE TABLE replies (
    message_id TEXT PRIMARY KEY REFERENCES messages(id), text TEXT NOT NULL,
    client_id TEXT UNIQUE NOT NULL, status TEXT NOT NULL, error TEXT,
    created_at REAL NOT NULL, context_id TEXT, attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE reply_parts (
    reply_id TEXT NOT NULL, part INTEGER NOT NULL, text TEXT NOT NULL,
    accepted INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(reply_id,part));
CREATE TABLE subscriptions (
    id TEXT PRIMARY KEY, principal TEXT NOT NULL, name TEXT NOT NULL,
    arguments TEXT NOT NULL, url TEXT NOT NULL, secret TEXT NOT NULL,
    old_secret TEXT, rotate_until REAL, expires_at REAL NOT NULL,
    verified_until REAL NOT NULL, status TEXT NOT NULL, start_rowid INTEGER NOT NULL);
CREATE TABLE deliveries (
    event_id TEXT PRIMARY KEY, subscription_id TEXT NOT NULL,
    message_id TEXT NOT NULL, body BLOB NOT NULL, status TEXT NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0, next_attempt REAL NOT NULL,
    error TEXT, UNIQUE(subscription_id,message_id));
CREATE TABLE event_metadata (key TEXT PRIMARY KEY,value TEXT);
"""
EVENT_TABLES = ("subscriptions", "deliveries", "event_metadata")


def legacy_fixture(state):
    state.mkdir(mode=0o700)
    database = state / "bridge.sqlite3"
    database.touch(mode=0o600)
    with closing(sqlite3.connect(database)) as db:
        db.executescript(LEGACY_SCHEMA)
        db.execute("INSERT INTO binding(id,owner,token,base_url,enabled) VALUES(?,?,?,?,1)",
                   ("fixture", "owner", "fixture-token", "https://ilinkai.weixin.qq.com"))
        db.execute("INSERT INTO messages VALUES(?,?,?,?,?,?,?,?)",
                   ("fixture-message", "fixture", "owner", "message:1", "synthetic inbound",
                    1, "synthetic-context", "replied"))
        db.execute("INSERT INTO replies VALUES(?,?,?,?,?,?,?,?)",
                   ("fixture-message", "x" * 10000, "fixture-reply", "sending", None,
                    2, "fixture-message", 1))
        db.executemany("INSERT INTO reply_parts VALUES(?,?,?,?)",
                       [("fixture-reply", 0, "x" * 3800, 1),
                        ("fixture-reply", 1, "x" * 3800, 0),
                        ("fixture-reply", 2, "x" * 2400, 0)])
        db.execute("INSERT INTO subscriptions VALUES(?,?,?,?,?,?,?,150,0,130,'active',0)",
                   ("fixture-subscription", '["fixture","owner"]', "weixin.message", "{}",
                    "https://callback.example.com/synthetic", "fixture-secret", "fixture-old-secret"))
        body = b'{"id":"fixture-event","data":{"message_id":"fixture-message"}}'
        db.execute("INSERT INTO deliveries VALUES(?,?,?,?,?,2,105,NULL)",
                   ("fixture-event", "fixture-subscription", "fixture-message", body, "sending"))
        db.execute("INSERT INTO event_metadata VALUES('nonexpiring_default:fixture-subscription','1')")
        db.commit()


def revision_fixture(root, temporary, state, revision):
    # Resolve first so a revision beginning with '-' cannot become an option.
    result = subprocess.run(["git", "rev-parse", "--verify", "--end-of-options",
                             revision + "^{commit}"], cwd=root, capture_output=True, text=True)
    commit = result.stdout.strip()
    if result.returncode or not re.fullmatch(r"[0-9a-f]{40,64}", commit):
        raise ValueError("old_revision_unavailable")
    archive = temporary / "old.tar"
    with archive.open("wb") as target:
        result = subprocess.run(["git", "archive", commit], cwd=root, stdout=target,
                                stderr=subprocess.PIPE)
    if result.returncode:
        raise ValueError("old_revision_unavailable")
    old = temporary / "old"
    old.mkdir(mode=0o700)
    with tarfile.open(archive) as source:
        source.extractall(old, filter="data")
    program = """
import sys
from wechat_dot_bridge.store import Store
s=Store(sys.argv[1])
s.import_binding(dict(id='fixture',owner='owner',token='fixture-token',base_url='https://ilinkai.weixin.qq.com'))
s.set_enabled(True)
s.ingest('fixture',[dict(source_id='1',peer='owner',text='fixture',created_at=1,context_token='fixture')],'cursor')
mid=s.list_pending()[0]['message_id'];s.queue_reply(mid,'x'*10000)
r=s.claim_send();s.finish_send(mid,'accepted',reply_id=r['reply_id']);s.claim_send();s.close()
"""
    result = subprocess.run([sys.executable, "-c", program, str(state)], cwd=old,
                            capture_output=True)
    if result.returncode:
        raise ValueError("old_revision_fixture_failed")


def event_snapshot(db):
    tables = {row[0] for row in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
    return {table: [tuple(row) for row in db.execute("SELECT * FROM " + table + " ORDER BY rowid")]
            for table in EVENT_TABLES if table in tables}


def verify(state, temporary):
    from wechat_dot_bridge.migrations import SCHEMA_VERSION
    from wechat_dot_bridge.operations import backup, restore
    from wechat_dot_bridge.store import Store

    with closing(sqlite3.connect(state / "bridge.sqlite3")) as db:
        original_events = event_snapshot(db)
    with closing(Store(state)) as store:
        assert store.db.execute("PRAGMA user_version").fetchone()[0] == SCHEMA_VERSION
        events = event_snapshot(store.db)
        assert set(events) == set(EVENT_TABLES)
        assert all(events[table] == rows for table, rows in original_events.items())
        store.recover_inflight()
        row = store.db.execute("SELECT client_id,message_id,status FROM replies").fetchone()
        assert row["status"] == "uncertain"
        assert store.send_status(row["message_id"])["parts_accepted"] == 1
        assert store.claim_send() is None
        snapshot = temporary / "backup.sqlite3"
        backup(store, snapshot)
    recovered = temporary / "recovered"
    recovered.mkdir(mode=0o700)
    restore(snapshot, recovered)
    with closing(Store(recovered)) as store:
        assert event_snapshot(store.db) == events
        assert not store.get_binding()["enabled"]
        assert store.claim_send() is None
        store.set_enabled(True)
        store.resolve_uncertain(row["client_id"], True)
        assert store.send_status(row["message_id"])["parts_accepted"] == 2
        assert store.claim_send() is not None


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--old-revision", help="Optional local Git revision; otherwise use the frozen legacy fixture")
    args = parser.parse_args(argv)
    root = Path(__file__).resolve().parent.parent
    sys.path.insert(0, str(root))
    try:
        with tempfile.TemporaryDirectory(prefix="bridge-upgrade-") as directory:
            temporary = Path(directory)
            state = temporary / "state"
            if args.old_revision is None:
                legacy_fixture(state)
            else:
                revision_fixture(root, temporary, state, args.old_revision)
            verify(state, temporary)
    except Exception as error:
        # Fixture and Git failures must not echo paths, command output or data.
        known = {"old_revision_unavailable", "old_revision_fixture_failed"}
        code = str(error) if isinstance(error, ValueError) and str(error) in known else "upgrade_verification_failed"
        print(json.dumps({"passed": False, "error": code}))
        return 1
    print("Upgrade, uncertain-send preservation, backup/restore and part recovery: passed (synthetic state only).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
